window.addEventListener('beforeprint',()=>{if(!circuit)return;beforePrint={selection,filter,notes:[...document.querySelectorAll('.wiring-notes')].map(n=>[n,n.open])};for(const [node] of beforePrint.notes)node.open=true;$('#generator-mount').innerHTML=drawCircuit(circuit,{exporting:true,mode});$('#generator-mount').style.width='100%';});window.addEventListener('afterprint',()=>{if(beforePrint){({selection,filter}=beforePrint);for(const [node,open] of beforePrint.notes)node.open=open;beforePrint=null;paintedCircuit=null;paint();}});$('#print-diagram').addEventListener('click',()=>window.print());
function syncSwitching(state){form.elements.prsSwitching.value=state.guitar==='prs-se'&&state.switching?'manual':'none';form.elements.prsState.value=state.switching?.[0]?.position||'down';for(const p of ['neck','bridge'])form.elements[p+'Bleed'].value=state.volumeBleeds?.[p]??state.bleed??'none';form.elements.bridgeSwitching.value=state.guitar==='hss'&&state.switching?'manual':'none';form.elements.pushpullState.value=state.switching?.find(m=>m.pickup==='bridge')?.position||'down';for(const p of ['neck','bridge']){form.elements[p+'ToneSwitching'].value=state.guitar!=='hss'&&state.switching?.some(m=>m.pickup===p)?'manual':'none';switchPositions[p]=state.switching?.find(m=>m.pickup===p)?.position||'down';}}
function setLayout(reset){const guitar=form.elements.guitar.value;if(reset)form.elements.controlLayout.value=guitar==='hh'?'1V1T':'1V2T';$('#generator-independent-bleeds').hidden=!['les-paul','sg'].includes(guitar);$('#generator-prs-switching').hidden=guitar!=='prs-se';$('#hss-control-layout').hidden=!['hss','hsh','strat','hh'].includes(guitar);form.elements.controlLayout.querySelector('[value="1V2T"]').textContent=guitar==='hh'?'1V2T · independent neck / bridge tones':guitar==='strat'?'1V2T · neck / middle tones':'1V2T · neck / middle + bridge tones';$('#hss-bridge-switching').hidden=guitar!=='hss';$('#hss-pushpull-state').hidden=true;for(const p of ['neck','bridge'])$('#lp-'+p+'-switching').hidden=!(['les-paul','sg'].includes(guitar)||guitar==='hsh'&&form.elements.controlLayout.value==='1V2T');const lp=['les-paul','sg'].includes(guitar),positions=form.elements.position,old=positions.value;positions.replaceChildren();for(const [v,label] of Object.entries(layoutInfo[guitar].positions)){const option=el('option',label);option.value=v;positions.append(option);}positions.value=!reset&&layoutInfo[guitar].positions[old]?old:lp?'both':'1';form.elements.wiring.disabled=!lp;form.elements.wiring.closest('label').hidden=!lp;if(!lp)form.elements.wiring.value='modern';$('#bridge-cap-control').hidden=!(lp||guitar==='hh'&&form.elements.controlLayout.value==='1V2T');form.elements.colours.disabled=['strat','tele'].includes(guitar);if(form.elements.colours.disabled)form.elements.colours.value='generic';if(reset){syncSwitching({});form.elements.neckCap.value=lp||['hss','hsh','hh','prs-se'].includes(guitar)?'0.022':'0.047';form.elements.bridgeCap.value=form.elements.neckCap.value;form.elements.bleed.value=guitar==='prs'?'prs':'none';}$('#generator-pickup-profiles').hidden=['strat','tele'].includes(guitar);$('#layout-description').textContent=layoutInfo[guitar].description;form.querySelector('.eyebrow').textContent=layoutInfo[guitar].description;}
function syncProfiles(){for(const ch of ['neck','bridge'])form.elements.namedItem(ch+'Profile').value=profiles[ch];}
for(const ch of ['neck','bridge'])for(const [id,entry] of Object.entries(pickupConventions)){const option=el('option',entry.label+(entry.verified?'':' · unsupported; generic shown'));option.value=id;form.elements.namedItem(ch+'Profile').append(option);}
const colourSelect=form.elements.colours;colourSelect.replaceChildren();for(const [id,entry] of Object.entries(pickupConventions)){const option=el('option',entry.label+(entry.verified?'':' · unverified'));option.value=id;colourSelect.append(option);}
let initialError='';try{const saved=readGeneratorURL(importedCircuit.notice&&!importedCircuit.state?'':location.search);requirePublicPlatform(saved.state);syncSwitching(saved.state);kitContext=saved.kit;profiles=saved.state.pickupProfiles||{neck:saved.state.colours,bridge:saved.state.colours};for(const [key,value] of Object.entries(saved.state))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value;if(kitContext&&['premium','overkill'].includes(kitContext.bleed)){const option=el('option',kitContext.bleed==='premium'?'Premium Sprague Duncan-style · supplied kit':'Apparition Overkill-Pasitor · supplied kit');option.value=kitContext.bleed;form.elements.bleed.append(option);form.elements.bleed.value=kitContext.bleed;}}catch(e){initialError=e.message;try{const requested=JSON.parse(new URLSearchParams(location.search).get('g')||'{}');if(requested.guitar==='hss'||requested.switching)unavailableReason=e.message;if(requested.guitar&&!['les-paul','sg','tele','strat','hss','hsh','hh','prs-se'].includes(requested.guitar))unavailableReason='This platform is not yet modelled by the public Wiring Generator.';}catch{}}
if(importedCircuit.state?.configuration){syncSwitching(importedCircuit.state.configuration);profiles=importedCircuit.state.configuration?.pickupProfiles||{neck:'generic',bridge:'generic'};if(kitContext){const saved=readGeneratorURL(location.search).state;if(!['wiring','bleed','neckCap','bridgeCap'].every(key=>saved[key]===importedCircuit.state.configuration[key]))kitContext=null;}for(const [key,value] of Object.entries(importedCircuit.state.configuration))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value;}else if(importedCircuit.notice)initialError=importedCircuit.notice;
syncProfiles();setLayout(false);if(importedCircuit.state?.configuration)form.elements.position.value=importedCircuit.state.configuration.position;
if(matchMedia('(max-width:800px)').matches)$('#generator-options').open=false;render();if(initialError&&!unavailableReason&&circuit)$('#generator-status').textContent=initialError+' The default circuit is shown.';

const projectRoot=el('section');projectRoot.className='local-projects';projectRoot.setAttribute('aria-label','Local circuit projects');document.querySelector('main').append(projectRoot);
mountProjectPanel(projectRoot,{getCircuit:()=>circuit,getProject:()=>projectContext,setProject:p=>{projectContext=p;unavailableReason='';importedCircuit={state:p?.electronics||null,notice:''};if(importedCircuit.state?.configuration){syncSwitching(importedCircuit.state.configuration);for(const [key,value] of Object.entries(importedCircuit.state.configuration))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value;setLayout(false);form.elements.position.value=importedCircuit.state.configuration.position;}render();},reset:()=>form.reset()});
$('#colour-legend').after(learningLink(document,'pickups','Pickup conductor colours explained'));
const learning=el('details');learning.append(el('summary','Learn about the wiring parts'));mountKnowledgeCards(learning,['selector','jack']);projectRoot.after(learning);
